+++ b/worker.go
@@ -0,0 +1,9 @@
+func sumSquares(items []int) int {
+	ch := make(chan int, len(items))
+	for i := 0; i < len(items); i++ {
+		go square(items[i], ch)
+	}
+	total := 0
+	for i := 0; i < len(items); i++ {
+		total += <-ch
+	}
+	return total
+}
+
+func square(n int, ch chan int) { ch <- n * n }
